import * as React from "react"
// Standalone Framer Shim for Next.js / React
const useIsStaticRenderer = () => false;
const addPropertyControls = () => {};
const ControlType = {
    Boolean: 'boolean', Number: 'number', String: 'string',
    Color: 'color', Enum: 'enum', Object: 'object',
    Array: 'array', Image: 'image', ResponsiveImage: 'responsiveImage',
    Font: 'font', Transition: 'transition', Link: 'link'
};


/**
 * Card Puzzle
 * A scroll-driven About / hero section: the name sits in the centre, six blurry
 * jigsaw pieces are scattered around the screen, and as the user scrolls they fly
 * together and sharpen into one clean white card (heading, text, CTA, portrait).
 *
 * Usage: place the component on a page and set its HEIGHT to about 320vh
 * (that height is the scroll distance). Width 100%.
 *
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 */

const COUNT = 6
const SCATTER_DESKTOP = [
    [0.13, 0.22, -22],
    [0.87, 0.22, 20],
    [0.1, 0.5, 14],
    [0.9, 0.5, -16],
    [0.13, 0.78, 18],
    [0.87, 0.78, -20],
]
const SCATTER_MOBILE = [
    [0.26, 0.12, -20],
    [0.76, 0.16, 16],
    [0.2, 0.5, 14],
    [0.8, 0.5, -18],
    [0.26, 0.88, 18],
    [0.76, 0.84, -16],
]

// Default portrait, generated in Gemini: a Tokyo-like city in the style of Van Gogh's The Starry Night.
// Replace it with your own through the "Portrait" property.
const DEFAULT_IMAGE =
    "data:image/jpeg;base64,"

const SERIF = "'DM Serif Display', Georgia, serif"
const SANS = "'Inter', system-ui, sans-serif"

const clamp = (v: number, a = 0, b = 1) => Math.min(b, Math.max(a, v))
const ease = (x: number) => Math.sin((x * Math.PI) / 2) // lands cleanly

type Geo = {
    mobile: boolean
    cols: number
    rows: number
    W: number
    H: number
    cw: number
    ch: number
    t: number
    nameSize: number
}

function computeGeo(width: number, height: number): Geo {
    const mobile = width < 720
    const cols = mobile ? 2 : 3
    const rows = COUNT / cols
    // desktop card takes about half the width
    const W = mobile
        ? width * 0.92
        : Math.min(Math.max(width * 0.5, 620), width * 0.92)
    const H = mobile
        ? Math.min(height * 0.8, W * 1.5)
        : Math.min(W * 0.6, height * 0.75)
    const cw = W / cols
    const ch = H / rows
    const t = 0.13 * Math.min(cw, ch)
    // the centre name matches the card heading size exactly
    const nameSize = mobile ? 44 : Math.min(84, Math.max(30, 0.072 * W))
    return { mobile, cols, rows, W, H, cw, ch, t, nameSize }
}

/* one jigsaw edge: p0 = start, u = direction, n = outward normal, s = +1 knob out / -1 knob in / 0 flat */
function edge(
    p0: number[],
    u: number[],
    n: number[],
    L: number,
    s: number,
    t: number
) {
    const end = [p0[0] + u[0] * L, p0[1] + u[1] * L]
    if (!s) return `L${end[0]} ${end[1]}`
    const c = L / 2
    const hw = 0.62 * t
    const nw = 0.3 * t
    const P = (a: number, b: number) =>
        [
            p0[0] + u[0] * a + n[0] * b * t * s,
            p0[1] + u[1] * a + n[1] * b * t * s,
        ].join(" ")
    return `L${P(c - nw, 0)} C${P(c - nw, 0.35)} ${P(c - hw, 0.45)} ${P(c - hw, 0.7)} C${P(c - hw, 1.05)} ${P(c + hw, 1.05)} ${P(c + hw, 0.7)} C${P(c + hw, 0.45)} ${P(c + nw, 0.35)} ${P(c + nw, 0)} L${end[0]} ${end[1]}`
}

// knob directions alternate in a checkerboard so every neighbouring pair interlocks
const hSign = (r: number, c: number) => ((r + c) % 2 ? 1 : -1)
const vSign = (r: number, c: number) => ((r + c) % 2 ? -1 : 1)

function piecePath(r: number, c: number, g: Geo) {
    const { cols, rows, cw, ch, t } = g
    const bw = cw + 2 * t
    const bh = ch + 2 * t
    const sTop = r > 0 ? -hSign(r - 1, c) : 0
    const sRight = c < cols - 1 ? vSign(r, c) : 0
    const sBottom = r < rows - 1 ? hSign(r, c) : 0
    const sLeft = c > 0 ? -vSign(r, c - 1) : 0
    let d = `M${t} ${t} `
    d += edge([t, t], [1, 0], [0, -1], cw, sTop, t) + " "
    d += edge([t + cw, t], [0, 1], [1, 0], ch, sRight, t) + " "
    d += edge([t + cw, t + ch], [-1, 0], [0, 1], cw, sBottom, t) + " "
    d += edge([t, t + ch], [0, -1], [-1, 0], ch, sLeft, t) + " Z"
    // normalise to 0..1 so the clip scales with the element
    return d.replace(
        /(-?\d*\.?\d+)\s(-?\d*\.?\d+)/g,
        (_m, x, y) => `${(x / bw).toFixed(5)} ${(y / bh).toFixed(5)}`
    )
}

type Props = {
    hiText: string
    name: string
    cardEyebrow: string
    cardTitle: string
    cardText: string
    ctaLabel: string
    ctaLink: string
    image?: { src: string; srcSet?: string; alt?: string }
    hintText: string
    background: string
    cardBackground: string
    ink: string
    muted: string
    accent: string
    style?: React.CSSProperties
}

export default function CardPuzzle(props: Props) {
    const {
        hiText,
        name,
        cardEyebrow,
        cardTitle,
        cardText,
        ctaLabel,
        ctaLink,
        image,
        hintText,
        background,
        cardBackground,
        ink,
        muted,
        accent,
    } = props

    const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "")
    const isCanvas = RenderTarget.current() === RenderTarget.canvas
    const isStatic = useIsStaticRenderer()

    const sectionRef = React.useRef<HTMLDivElement>(null)
    const pinRef = React.useRef<HTMLDivElement>(null)
    const stageRef = React.useRef<HTMLDivElement>(null)
    const finalRef = React.useRef<HTMLDivElement>(null)
    const hintRef = React.useRef<HTMLDivElement>(null)
    const pieceRefs = React.useRef<(HTMLDivElement | null)[]>([])
    const [geo, setGeo] = React.useState<Geo | null>(null)

    // fonts (DM Serif Display + Inter)
    React.useEffect(() => {
        const id = "card-puzzle-fonts"
        if (document.getElementById(id)) return
        const l = document.createElement("link")
        l.id = id
        l.rel = "stylesheet"
        l.href =
            "https://fonts.googleapis.com/css2?family=DM+Serif+Display&family=Inter:wght@400;500;600&display=swap"
        document.head.appendChild(l)
    }, [])

    // geometry from the section width and the viewport height
    React.useEffect(() => {
        const pin = pinRef.current
        if (!pin) return
        if (isStatic) {
            setGeo(computeGeo(pin.clientWidth || 1200, 800))
            return
        }
        const measure = () => {
            const g = computeGeo(
                pin.clientWidth || window.innerWidth,
                isCanvas ? 800 : window.innerHeight
            )
            setGeo((prev) =>
                prev && JSON.stringify(prev) === JSON.stringify(g) ? prev : g
            )
        }
        measure()
        const ro = new ResizeObserver(measure)
        ro.observe(pin)
        window.addEventListener("resize", measure)
        return () => {
            ro.disconnect()
            window.removeEventListener("resize", measure)
        }
    }, [isCanvas, isStatic])

    // scroll-driven animation
    React.useEffect(() => {
        if (!geo) return
        const section = sectionRef.current
        const pin = pinRef.current
        const stage = stageRef.current
        const fin = finalRef.current
        const hint = hintRef.current
        if (!section || !pin || !stage || !fin) return

        const reduced =
            isCanvas ||
            window.matchMedia("(prefers-reduced-motion: reduce)").matches
        const scatter = geo.mobile ? SCATTER_MOBILE : SCATTER_DESKTOP
        let cur = 0
        let raf = 0
        let done: boolean | null = null
        let hideTimer: any = 0

        const readProgress = () => {
            if (reduced) return 1
            const r = section.getBoundingClientRect()
            const range = r.height - window.innerHeight
            return range > 0 ? clamp(-r.top / range) : 0
        }

        const render = (p: number) => {
            const sx = stage.offsetLeft
            const sy = stage.offsetTop
            let minE = 1
            pieceRefs.current.forEach((el, i) => {
                if (!el) return
                const e = ease(clamp((p - 0.04 - i * 0.05) / 0.5))
                minE = Math.min(minE, e)
                const k = 1 - e
                const [fx, fy, rot] = scatter[i]
                const r = Math.floor(i / geo.cols)
                const c = i % geo.cols
                const cx = c * geo.cw + geo.cw / 2
                const cy = r * geo.ch + geo.ch / 2
                // vector from the piece's final centre to its scattered centre
                const dx = fx * pin.clientWidth - (sx + cx)
                const dy = fy * pin.clientHeight - (sy + cy)
                el.style.transform = `translate(${dx * k}px, ${dy * k}px) rotate(${rot * k}deg) scale(${1 - 0.06 * k})`
                el.style.filter = `drop-shadow(0 14px 22px rgba(42, 26, 18, ${(0.22 * k).toFixed(3)}))`
                const card = (el.firstChild as HTMLElement)
                    ?.firstChild as HTMLElement
                if (card)
                    card.style.filter =
                        k > 0.001 ? `blur(${(k * 16).toFixed(2)}px)` : "none"
                el.style.zIndex = String(Math.round(k * 10))
            })

            // once the last piece is home, fade (over time) into one clean identical card, then drop the pieces
            const complete = minE >= 0.995
            if (complete !== done) {
                done = complete
                fin.style.opacity = complete ? "1" : "0"
                fin.style.transform = complete ? "none" : "scale(1.012)"
                fin.style.pointerEvents = complete ? "auto" : "none"
                clearTimeout(hideTimer)
                if (complete) {
                    hideTimer = setTimeout(
                        () =>
                            pieceRefs.current.forEach(
                                (el) => el && (el.style.visibility = "hidden")
                            ),
                        520
                    )
                } else {
                    pieceRefs.current.forEach(
                        (el) => el && (el.style.visibility = "visible")
                    )
                }
            }
            if (hint) hint.style.opacity = p > 0.05 ? "0" : "1"
        }

        // displayed progress eases toward the scroll position so wheel ticks glide
        const tick = () => {
            const target = readProgress()
            cur += (target - cur) * 0.12
            if (Math.abs(target - cur) < 0.0004) cur = target
            render(cur)
            raf = cur === target ? 0 : requestAnimationFrame(tick)
        }
        const kick = () => {
            if (!raf) raf = requestAnimationFrame(tick)
        }

        if (isStatic) {
            render(1)
            return () => clearTimeout(hideTimer)
        }
        cur = readProgress()
        render(cur)
        window.addEventListener("scroll", kick, { passive: true })
        window.addEventListener("resize", kick)
        return () => {
            window.removeEventListener("scroll", kick)
            window.removeEventListener("resize", kick)
            cancelAnimationFrame(raf)
            clearTimeout(hideTimer)
        }
    }, [geo, isCanvas, isStatic])

    const nameLines = String(name || "").split(" ")

    // the card is written once and rendered inside every piece and as the final card
    const cardContent = (g: Geo) => (
        <>
            <div
                style={{
                    flex: "1 1 58%",
                    padding: g.mobile
                        ? "20px 22px 24px"
                        : "clamp(20px, 5cqw, 56px)",
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                    alignItems: "flex-start",
                    gap: g.mobile ? 10 : 16,
                }}
            >
                <div
                    style={{
                        fontFamily: SANS,
                        fontSize: 12,
                        letterSpacing: "0.18em",
                        textTransform: "uppercase",
                        color: accent,
                        fontWeight: 600,
                    }}
                >
                    {cardEyebrow}
                </div>
                <h2
                    style={{
                        margin: 0,
                        fontFamily: SERIF,
                        fontWeight: 400,
                        fontSize: g.nameSize,
                        lineHeight: 0.98,
                        color: ink,
                    }}
                >
                    {cardTitle}
                </h2>
                <p
                    style={{
                        margin: 0,
                        fontFamily: SANS,
                        fontSize: "clamp(13px, 1.9cqw, 18px)",
                        lineHeight: 1.55,
                        color: muted,
                        maxWidth: "34ch",
                    }}
                >
                    {cardText}
                </p>
                <a
                    href={ctaLink || "#"}
                    style={{
                        display: "inline-flex",
                        alignItems: "center",
                        gap: 10,
                        marginTop: 6,
                        padding: g.mobile
                            ? "12px 20px"
                            : "clamp(10px, 1.9cqw, 14px) clamp(18px, 3.2cqw, 24px)",
                        borderRadius: 99,
                        background: ink,
                        color: cardBackground,
                        fontFamily: SANS,
                        fontWeight: 600,
                        fontSize: g.mobile ? 14 : 15,
                        textDecoration: "none",
                    }}
                >
                    {ctaLabel} <span aria-hidden="true">→</span>
                </a>
            </div>
            <div
                style={{
                    flex: g.mobile ? "0 0 44%" : "0 0 40%",
                    padding: g.mobile ? "12px 12px 0" : "16px 16px 16px 0",
                    order: g.mobile ? -1 : 0,
                }}
            >
                <img
                    src={image?.src || DEFAULT_IMAGE}
                    srcSet={image?.src ? image.srcSet : undefined}
                    alt={
                        image?.alt ||
                        "Tokyo skyline painted in the style of Van Gogh's Starry Night"
                    }
                    style={{
                        width: "100%",
                        height: "100%",
                        objectFit: "cover",
                        borderRadius: 18,
                        display: "block",
                    }}
                />
            </div>
        </>
    )

    const cardBase = (g: Geo): React.CSSProperties =>
        ({
            position: "absolute",
            background: cardBackground,
            borderRadius: 28,
            overflow: "hidden",
            display: "flex",
            flexDirection: g.mobile ? "column" : "row",
            color: ink,
            containerType: "inline-size",
            width: g.W,
            height: g.H,
        }) as any

    return (
        <div
            ref={sectionRef}
            style={{
                position: "relative",
                width: "100%",
                height: "100%",
                minHeight: "100vh",
                background,
            }}
        >
            <div
                ref={pinRef}
                style={{
                    position: isCanvas ? "relative" : "sticky",
                    top: 0,
                    height: isCanvas ? 800 : "100vh",
                    overflow: "hidden",
                }}
            >
                {geo && (
                    <svg
                        width="0"
                        height="0"
                        style={{ position: "absolute" }}
                        aria-hidden="true"
                    >
                        <defs>
                            {Array.from({ length: COUNT }).map((_, i) => (
                                <clipPath
                                    key={i}
                                    id={`cp${uid}${i}`}
                                    clipPathUnits="objectBoundingBox"
                                >
                                    <path
                                        d={piecePath(
                                            Math.floor(i / geo.cols),
                                            i % geo.cols,
                                            geo
                                        )}
                                    />
                                </clipPath>
                            ))}
                        </defs>
                    </svg>
                )}

                {/* centre text, sits behind the card */}
                <div
                    style={{
                        position: "absolute",
                        inset: 0,
                        display: "grid",
                        placeItems: "center",
                        textAlign: "center",
                        zIndex: 0,
                    }}
                >
                    <div>
                        <div
                            style={{
                                fontFamily: SANS,
                                fontSize: "clamp(14px, 1.5vw, 20px)",
                                letterSpacing: "0.18em",
                                textTransform: "uppercase",
                                color: accent,
                                fontWeight: 600,
                                marginBottom: 14,
                            }}
                        >
                            {hiText}
                        </div>
                        <h1
                            style={{
                                margin: 0,
                                fontFamily: SERIF,
                                fontWeight: 400,
                                lineHeight: 0.98,
                                color: ink,
                                fontSize: geo ? geo.nameSize : 52,
                            }}
                        >
                            {nameLines.map((l, i) => (
                                <React.Fragment key={i}>
                                    {l}
                                    {i < nameLines.length - 1 && <br />}
                                </React.Fragment>
                            ))}
                        </h1>
                    </div>
                </div>

                {geo && (
                    <div
                        ref={stageRef}
                        style={{
                            position: "absolute",
                            left: "50%",
                            top: "50%",
                            zIndex: 1,
                            width: geo.W,
                            height: geo.H,
                            marginLeft: -geo.W / 2,
                            marginTop: -geo.H / 2,
                        }}
                    >
                        {Array.from({ length: COUNT }).map((_, i) => {
                            const r = Math.floor(i / geo.cols)
                            const c = i % geo.cols
                            return (
                                <div
                                    key={i}
                                    ref={(el) => {
                                        pieceRefs.current[i] = el
                                    }}
                                    style={{
                                        position: "absolute",
                                        willChange: "transform, opacity",
                                        left: c * geo.cw - geo.t,
                                        top: r * geo.ch - geo.t,
                                        width: geo.cw + 2 * geo.t,
                                        height: geo.ch + 2 * geo.t,
                                    }}
                                >
                                    <div
                                        style={{
                                            width: "100%",
                                            height: "100%",
                                            position: "relative",
                                            overflow: "hidden",
                                            clipPath: `url(#cp${uid}${i})`,
                                        }}
                                    >
                                        {/* every piece holds a full copy of the card, shifted to show only its own cell */}
                                        <div
                                            aria-hidden="true"
                                            style={{
                                                ...cardBase(geo),
                                                left: geo.t - c * geo.cw,
                                                top: geo.t - r * geo.ch,
                                                willChange: "filter",
                                            }}
                                        >
                                            {cardContent(geo)}
                                        </div>
                                    </div>
                                </div>
                            )
                        })}

                        <div
                            ref={finalRef}
                            style={{
                                ...cardBase(geo),
                                left: 0,
                                top: 0,
                                zIndex: 20,
                                opacity: 0,
                                transform: "scale(1.012)",
                                pointerEvents: "none",
                                boxShadow: "0 14px 40px rgba(42, 26, 18, 0.14)",
                                transition:
                                    "opacity .5s ease, transform .7s cubic-bezier(.2,.7,.2,1)",
                            }}
                        >
                            {cardContent(geo)}
                        </div>
                    </div>
                )}

                <div
                    ref={hintRef}
                    style={{
                        position: "absolute",
                        bottom: 24,
                        left: 0,
                        right: 0,
                        textAlign: "center",
                        fontFamily: SANS,
                        fontSize: 12,
                        letterSpacing: "0.12em",
                        textTransform: "uppercase",
                        color: muted,
                        transition: "opacity .3s",
                    }}
                >
                    {hintText}
                </div>
            </div>
        </div>
    )
}

CardPuzzle.defaultProps = {
    hiText: "Hi, I am",
    name: "Shubhangi Sharma",
    cardEyebrow: "Hello, I'm",
    cardTitle: "Product Designer",
    cardText:
        "Photographer and video editor, good at turning quiet, golden moments into stories people remember.",
    ctaLabel: "Connect",
    ctaLink: "#connect",
    hintText: "Scroll to assemble",
    background: "#f1e8dc",
    cardBackground: "#ffffff",
    ink: "#2a1a12",
    muted: "#6d5646",
    accent: "#a9502d",
    width: 1200,
    height: 2600,
}

addPropertyControls(CardPuzzle, {
    hiText: { type: ControlType.String, title: "Intro" },
    name: { type: ControlType.String, title: "Name" },
    cardEyebrow: { type: ControlType.String, title: "Eyebrow" },
    cardTitle: { type: ControlType.String, title: "Heading" },
    cardText: {
        type: ControlType.String,
        title: "Text",
        displayTextArea: true,
    },
    ctaLabel: { type: ControlType.String, title: "Button" },
    ctaLink: { type: ControlType.Link, title: "Link" },
    image: { type: ControlType.ResponsiveImage, title: "Portrait" },
    hintText: { type: ControlType.String, title: "Hint" },
    background: { type: ControlType.Color, title: "Background" },
    cardBackground: { type: ControlType.Color, title: "Card" },
    ink: { type: ControlType.Color, title: "Text" },
    muted: { type: ControlType.Color, title: "Muted" },
    accent: { type: ControlType.Color, title: "Accent" },
})
